// Labeling throughput index — record JAH-GGN-LABELMAKER-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tape_width_mm": 12, "print_speed_mms": 20, "price_usd": 30};
var value = (m.tape_width_mm*m.print_speed_mms/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGN-LABELMAKER-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGN-LABELMAKER-000001|' + value.toFixed(2) + ' throughput index');

